# ============================================================# migrate-to-banf-jax.ps1# Automated migration: ranadhir19 -> banf-jax# Run from: c:\projects\banf\# Prerequisites: Phase 1 of GITHUB_MIGRATION_PLAN.md complete# ============================================================param(    [switch]$DryRun,       # Show what would change without modifying files    [switch]$SkipPush,     # Skip git push (useful for review before pushing)    [switch]$SkipWixPublish # Skip Wix publish)$ErrorActionPreference = "Stop"$ROOT = "c:\projects\banf"$OLD  = "ranadhir19"$NEW  = "banfjax-hash"# Ensure Node.js is in PATH$env:PATH = "C:\Program Files\nodejs;" + $env:PATHWrite-Host ""Write-Host "========================================================" -ForegroundColor CyanWrite-Host "  BANF GitHub Migration: ranadhir19 -> banf-jax         " -ForegroundColor CyanWrite-Host "========================================================" -ForegroundColor CyanWrite-Host ""if ($DryRun) {    Write-Host "  *** DRY RUN MODE -- no files will be modified ***" -ForegroundColor Yellow    Write-Host ""}# ============================================================# PHASE 2: Find and replace all references# ============================================================Write-Host "=== Phase 2: Updating code references ===" -ForegroundColor Green# Files to update (Category A-E from migration plan)# We process specific source files, NOT agent_reports JSON logs$filesToUpdate = @(    # Category A - Wix Backend (critical, affects live emails)    "banf1-wix\src\backend\banf-evite-report.js",    "banf1-wix\src\backend\banf-survey.js",    "banf1-wix\src\backend\email-templates.js",    "banf1-wix\src\backend\admin-onboarding.js",    "banf1-wix\src\backend\comms-correction.js",    "banf1-wix\src\backend\http-functions.js",    "banf1-wix\src\backend\banf-rag-context.js",    "banf1-wix\src\pages\CommsForm.js",    # Category B - GitHub Pages HTML    "banf1\admin-portal.html",    # Category C - Other Source Files    "banf1\banf_web\gmail_service.py",    "stage3-launch.js",    "banf1-wix\scripts\test-membership-onboarding.ps1",    # Category D - Documentation (root level)    "BANF_COMPLETE_PUBLISH_AND_TEST_GUIDE.md",    "DEPLOYMENT_SUMMARY.md",    # Category D - Documentation (banf1)    "banf1\DEPLOYMENT_GUIDE.md",    "banf1\PUBLISH_FROM_OTHER_MACHINE.md",    "banf1\BANF_COMPLETE_PUBLISH_AND_TEST_GUIDE.md",    # Category D - Documentation (banf1-wix)    "banf1-wix\PUBLISH_FROM_OTHER_MACHINE.md",    "banf1-wix\DEPLOYMENT_GUIDE.md",    "banf1-wix\survey\banf_web\BACKEND_PUSH_COMPLETE.md",    "banf1-wix\survey\banf_web\API_ISSUES_REPORT.md",    # Category D - Documentation (mirror copies)    "banf1-wix\banf1-mirror\PUBLISH_FROM_OTHER_MACHINE.md",    "banf1-wix\banf1-mirror\DEPLOYMENT_GUIDE.md",    "banf1-wix\banf1-mirror\BANF_COMPLETE_PUBLISH_AND_TEST_GUIDE.md",    "banf1-wix\banf1-mirror\admin-portal.html",    "banf1-wix\banf1-mirror\banf_web\gmail_service.py",    # Category E - Generated/Preview Files    "output\email-preview.html",    "output\survey-preview.html",    # Root-level markdown files    "WIX_DEPLOYMENT_AGENT.md")# Check for the special-char filename separately$quickRefPath = Join-Path $ROOT ([char]0x26A1 + "_QUICK_REFERENCE.md")$hasQuickRef = Test-Path $quickRefPath$totalReplaced = 0$filesModified = 0foreach ($relPath in $filesToUpdate) {    $fullPath = Join-Path $ROOT $relPath    if (-not (Test-Path $fullPath)) {        Write-Host "  SKIP (not found): $relPath" -ForegroundColor DarkGray        continue    }    $content = Get-Content $fullPath -Raw -Encoding UTF8    $count = ([regex]::Matches($content, [regex]::Escape($OLD))).Count    if ($count -eq 0) {        Write-Host "  SKIP (0 matches): $relPath" -ForegroundColor DarkGray        continue    }    if (-not $DryRun) {        $newContent = $content -replace [regex]::Escape($OLD), $NEW        [System.IO.File]::WriteAllText($fullPath, $newContent, [System.Text.UTF8Encoding]::new($false))    }    Write-Host "  OK  $relPath ($count replacements)" -ForegroundColor White    $totalReplaced += $count    $filesModified++}# Handle quick reference file with special char in nameif ($hasQuickRef) {    $content = Get-Content $quickRefPath -Raw -Encoding UTF8    $count = ([regex]::Matches($content, [regex]::Escape($OLD))).Count    if ($count -gt 0) {        if (-not $DryRun) {            $newContent = $content -replace [regex]::Escape($OLD), $NEW            [System.IO.File]::WriteAllText($quickRefPath, $newContent, [System.Text.UTF8Encoding]::new($false))        }        Write-Host "  OK  QUICK_REFERENCE.md ($count replacements)" -ForegroundColor White        $totalReplaced += $count        $filesModified++    }}Write-Host ""Write-Host "  Total: $totalReplaced replacements across $filesModified files" -ForegroundColor CyanWrite-Host ""if ($DryRun) {    Write-Host "  Dry run complete. Re-run without -DryRun to apply changes." -ForegroundColor Yellow    exit 0}# ============================================================# PHASE 3: Update git remotes, commit, and push# ============================================================Write-Host "=== Phase 3: Updating git remotes ===" -ForegroundColor Green# --- banf1 repo ---Write-Host "  Updating banf1 remote..." -ForegroundColor WhitePush-Location (Join-Path $ROOT "banf1")git remote set-url origin "https://github.com/$NEW/banf1.git"$newRemote = git remote get-url originWrite-Host "  OK  banf1 origin -> $newRemote" -ForegroundColor WhiteWrite-Host "  Committing banf1 changes..." -ForegroundColor Whitegit add -Agit commit -m "chore: migrate GitHub from ranadhir19 to banf-jax" --allow-empty 2>&1 | Out-Nullif (-not $SkipPush) {    Write-Host "  Pushing banf1 (all branches + tags)..." -ForegroundColor White    git push -u origin --all 2>&1    git push origin --tags 2>&1    Write-Host "  OK  banf1 pushed to banf-jax/banf1" -ForegroundColor Green} else {    Write-Host "  SKIPPED push (use without -SkipPush to push)" -ForegroundColor Yellow}Pop-LocationWrite-Host ""# --- banf1-wix repo ---Write-Host "  Updating banf1-wix remote..." -ForegroundColor WhitePush-Location (Join-Path $ROOT "banf1-wix")git remote set-url origin "https://github.com/$NEW/banf1-wix.git"$newRemote = git remote get-url originWrite-Host "  OK  banf1-wix origin -> $newRemote" -ForegroundColor WhiteWrite-Host "  Committing banf1-wix changes..." -ForegroundColor Whitegit add -Agit commit -m "chore: migrate GitHub from ranadhir19 to banf-jax" --allow-empty 2>&1 | Out-Nullif (-not $SkipPush) {    Write-Host "  Pushing banf1-wix (all branches + tags)..." -ForegroundColor White    git push -u origin --all 2>&1    git push origin --tags 2>&1    Write-Host "  OK  banf1-wix pushed to banf-jax/banf1-wix" -ForegroundColor Green} else {    Write-Host "  SKIPPED push (use without -SkipPush to push)" -ForegroundColor Yellow}Pop-LocationWrite-Host ""# ============================================================# PHASE 4: Publish Wix backend# ============================================================if (-not $SkipWixPublish) {    Write-Host "=== Phase 4: Publishing Wix backend ===" -ForegroundColor Green    Push-Location (Join-Path $ROOT "banf1-wix")    Write-Host "  Running wix publish..." -ForegroundColor White    node "node_modules/@wix/cli/bin/wix.cjs" publish -y    Write-Host "  OK  Wix backend published" -ForegroundColor Green    Pop-Location} else {    Write-Host "=== Phase 4: SKIPPED Wix publish ===" -ForegroundColor Yellow}Write-Host ""# ============================================================# Summary# ============================================================Write-Host "========================================================" -ForegroundColor GreenWrite-Host "  Migration Complete!                                    " -ForegroundColor GreenWrite-Host "========================================================" -ForegroundColor GreenWrite-Host ""Write-Host "  Next manual steps:" -ForegroundColor YellowWrite-Host "  1. Enable GitHub Pages: https://github.com/banf-jax/banf1/settings/pages" -ForegroundColor WhiteWrite-Host "     Branch: main, Folder: /docs (or root)" -ForegroundColor DarkGrayWrite-Host "  2. Verify: https://banf-jax.github.io/banf1/rsvp.html" -ForegroundColor WhiteWrite-Host "  3. Verify: https://banf-jax.github.io/banf1/survey.html" -ForegroundColor WhiteWrite-Host "  4. Optional: Archive old repos at github.com/ranadhir19" -ForegroundColor DarkGrayWrite-Host ""